<?phpnamespace app\api\service\business;use app\api\service\CommService;use app\common\model\business\MallHospital;class HospitalService extends CommService{    public function __construct($param, $user_info)    {        parent::_initialize($param, $user_info);    }    /**     * 医院列表     */    public function getHospitalList()    {        $where[] = ['status', '=', 1];        if (!empty($this->param['keyword'])) {            $where[] = ['name', 'like', '%' . $this->param['keyword'] . '%'];        }        $hospital_list = MallHospital::where($where)->field('hospital_id,initial,name,logo,address')->order('sort desc')->select();        $this->data['hospital_list'] = $hospital_list;        return $this->data;    }    /**     * 医院详情     */    public function getHospitalDetail()    {        $where[] = ['hospital_id', '=', $this->param['hospital_id']];        $where[] = ['status', '=', 1];        $hospital = MallHospital::where($where)->field('hospital_id,initial,name,logo,address,introduction,visit_code_process')->find();        $this->data['hospital'] = $hospital;        // 获取医院科室列表//        $departmentModel = new MallDepartment();//        $departments = $departmentModel->getHospitalDepartments($this->param['hospital_id'], 'department_id, name, initial');//        $hospital->departments = $departments;        return $this->data;    }}